import java.util.*;

class Solution {
  public int findRotateSteps(String ring, String key) {
    int n = ring.length(), m = key.length();
    List<List<Integer>> positions = new ArrayList<>();
    for (int c = 0; c < 26; c++) positions.add(new ArrayList<>());
    for (int i = 0; i < n; i++) positions.get(ring.charAt(i) - 'a').add(i);
    // dp[i]: fewest rotations to have spelled key so far with the ring at position i
    int[] dp = new int[n];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    List<Integer> prevPositions = Collections.singletonList(0);
    for (int k = 0; k < m; k++) {
      int[] next = new int[n];
      Arrays.fill(next, Integer.MAX_VALUE);
      List<Integer> cur = positions.get(key.charAt(k) - 'a');
      for (int to : cur)
        for (int from : prevPositions) {
          int diff = Math.abs(to - from), steps = Math.min(diff, n - diff);
          next[to] = Math.min(next[to], dp[from] + steps);
        }
      dp = next;
      prevPositions = cur;
    }
    int best = Integer.MAX_VALUE;
    for (int p : prevPositions) best = Math.min(best, dp[p]);
    return best + m; // one press per character
  }
}
